'use strict';
const SERVICES_BASE6={fresh,validateSave};
function ensureServices6(v){if(v.services6===undefined)v.services6={history:[]};return v;}
fresh=function(...args){return ensureServices6(SERVICES_BASE6.fresh(...args));};ensureServices6(state);
function serviceAllQuote6(scope='all'){if(!['all','cafes','factories'].includes(scope))throw Error('Vyber rozsah servisu.');const items=[];if(scope!=='factories')for(const s of state.stores.filter(s=>!s.franchise)){const before=items.length;for(const [key,e] of Object.entries(s.equipment))if(e.condition<100)items.push({kind:'equipment',target:s.id,key,model:e.model||'standard',name:loc(s.id).name+' · '+equipmentSpec5(key,e).name,before:e.condition,cost:round(equipmentSpec5(key,e).cost*.08)});if(items.length===before&&s.serviceCondition<100)items.push({kind:'premises',target:s.id,key:null,name:loc(s.id).name+' · provozní kontrola',before:s.serviceCondition,cost:5000});}if(scope!=='cafes'){for(const r of state.roasters)if(r.tenure6!=='contract'&&r.condition<100)items.push({kind:'roaster',target:r.id,key:null,name:r.name+(r.tenure6==='contract'?' · servis dodavatele':''),before:r.condition,cost:r.tenure6==='contract'?0:18000});for(const b of state.bakery5.bakeries)if(b.condition<100)items.push({kind:'bakery',target:b.id,key:null,name:b.name,before:b.condition,cost:b.cost*.04});}return {scope,week:state.week,cash:state.cash,items,total:items.reduce((n,x)=>n+x.cost,0)};}
function serviceAll6(scope='all',expected){guard();const q=serviceAllQuote6(scope);if(expected&&JSON.stringify(q)!==JSON.stringify(expected))throw Error('Zařízení, cena nebo hotovost se změnily. Obnov nabídku servisu.');if(!q.items.length)throw Error('Vše v tomto rozsahu je již v plném technickém stavu.');if(state.cash<q.total)throw Error('Na celý servis chybí hotovost. Vyber menší rozsah nebo ponech opravy na později.');const before=JSON.parse(JSON.stringify(state));try{for(const x of q.items){if(x.kind==='equipment')serviceEquipment(x.target,x.key);else if(x.kind==='roaster')maintainRoaster(x.target);else if(x.kind==='bakery')serviceBakery5(x.target);else{spend(x.cost);state.stores.find(s=>s.id===x.target).serviceCondition=100;state.pendingExpense3=(state.pendingExpense3||0)+x.cost;log('Provozní kontrola: '+loc(x.target).name,money(x.cost)+' · stav obnoven na 100 %.');}}const receipt={id:uid('serviceall'),week:state.week,scope,total:q.total,cashBefore:q.cash,cashAfter:state.cash,items:q.items.map(x=>({...x,after:100}))};state.services6.history.push(receipt);state.services6.history=state.services6.history.slice(-26);log('Společný servis dokončen',q.items.length+' oprav · '+money(q.total)+'. Jednotlivé placené opravy se objeví v nejbližším výsledku firmy.');return receipt;}catch(error){state=before;throw error;}}
validateSave=function(input){const v=SERVICES_BASE6.validateSave(input);ensureServices6(v);const n=(x,min=0,max=1e12)=>Number.isFinite(x)&&x>=min&&x<=max,str=(x,max)=>typeof x==='string'&&x.length<=max,fail=()=>{throw Error('Soubor obsahuje neplatnou účtenku společného servisu.');};if(!Array.isArray(v.services6.history)||v.services6.history.length>26||new Set(v.services6.history.map(x=>x.id)).size!==v.services6.history.length)fail();let week=0;for(const h of v.services6.history){if(!str(h.id,60)||!/^serviceall-[0-9]+$/.test(h.id)||!Number.isInteger(h.week)||h.week<week||h.week>v.week||!['all','cafes','factories'].includes(h.scope)||!n(h.total)||!n(h.cashBefore)||!n(h.cashAfter)||Math.abs(h.cashBefore-h.cashAfter-h.total)>.01||!Array.isArray(h.items)||!h.items.length||h.items.length>1500||new Set(h.items.map(x=>x.kind+'|'+x.target+'|'+x.key)).size!==h.items.length||Math.abs(h.total-h.items.reduce((n,x)=>n+x.cost,0))>.01)fail();week=h.week;for(const x of h.items)if(!['equipment','premises','roaster','bakery'].includes(x.kind)||!str(x.target,60)||!str(x.name,140)||!n(x.before,0,100)||x.before>=100||x.after!==100||!n(x.cost)||x.kind==='equipment'&&(!loc(x.target)||!Object.hasOwn(EQUIPMENT,x.key)||(EQUIPMENT_MODELS5[x.key]?!Object.hasOwn(EQUIPMENT_MODELS5[x.key],x.model):x.model!=='standard')||x.cost!==round(equipmentSpec5(x.key,{model:x.model}).cost*.08))||x.kind==='premises'&&(!loc(x.target)||x.key!==null||x.cost!==5000)||['roaster','bakery'].includes(x.kind)&&x.key!==null)fail();}return v;};
